import (
	"encoding/json"
	"os"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsPath 是按仓库配置低库存阈值的 JSON 文件，形如 {"shanghai": 20}。
// 相对进程工作目录解析。
const thresholdsPath = "inventory/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 优先取 thresholds.json 中该仓库的配置；文件不存在、解析失败或该仓库未配置时，
// 回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := loadThresholds(thresholdsPath)[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取 path 指向的 JSON 阈值表。
// 任何读取或解析错误都视为没有可用配置，返回 nil。
func loadThresholds(path string) map[string]int {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

