package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// writeThresholds 在 dir 下创建 inventory/thresholds.json 并写入 contents，
// 让进程以 dir 为工作目录时能读到该配置。
func writeThresholds(t *testing.T, dir, contents string) {
	t.Helper()
	thresholdsDir := filepath.Join(dir, "inventory")
	if err := os.MkdirAll(thresholdsDir, 0o755); err != nil {
		t.Fatalf("创建 %s 失败: %v", thresholdsDir, err)
	}
	if err := os.WriteFile(filepath.Join(thresholdsDir, "thresholds.json"), []byte(contents), 0o644); err != nil {
		t.Fatalf("写入 thresholds.json 失败: %v", err)
	}
}

// chdir 把工作目录切到 dir，测试结束后恢复。
func chdir(t *testing.T, dir string) {
	t.Helper()
	old, err := os.Getwd()
	if err != nil {
		t.Fatalf("获取当前目录失败: %v", err)
	}
	if err := os.Chdir(dir); err != nil {
		t.Fatalf("切换到 %s 失败: %v", dir, err)
	}
	t.Cleanup(func() {
		if err := os.Chdir(old); err != nil {
			t.Fatalf("恢复当前目录失败: %v", err)
		}
	})
}

func TestConfiguredWarehouseUsesItsOwnThreshold(t *testing.T) {
	dir := t.TempDir()
	writeThresholds(t, dir, `{"shanghai": 20}`)
	chdir(t, dir)

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望 20", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库应回退默认值，得到 %d", got)
	}
	if !IsLowStock("shanghai", 19) {
		t.Fatal("19 低于 shanghai 的阈值 20，应算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("等于 shanghai 的阈值 20 不算低库存（严格小于）")
	}
}

func TestMissingThresholdsFileFallsBackToDefault(t *testing.T) {
	dir := t.TempDir()
	chdir(t, dir)

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件不存在时应回退默认值，得到 %d", got)
	}
}

func TestMalformedThresholdsFileFallsBackToDefault(t *testing.T) {
	dir := t.TempDir()
	writeThresholds(t, dir, `{"shanghai":`)
	chdir(t, dir)

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件损坏时应回退默认值，得到 %d", got)
	}
}

func TestLowStockWarehousesUsesPerWarehouseThresholds(t *testing.T) {
	dir := t.TempDir()
	writeThresholds(t, dir, `{"shanghai": 20}`)
	chdir(t, dir)

	got := LowStockWarehouses(map[string]int{"shanghai": 15, "chengdu": 4, "xian": 99})
	want := []string{"chengdu", "shanghai"}
	if len(got) != len(want) {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
		}
	}
}
